function EXTRA(R,ICON){
 /* hook: the motor-generator loop, and an honest turbine */
 ICON.thLoop=(x,y)=>`<g transform="translate(${x-190} ${y-85})">${TH_box(0,0,380,170,{fill:'#FFFFFF',st:TH_GREY,sw:3,r:18})}
  <circle cx="76" cy="78" r="40" fill="${TH_SKY}" stroke="${BLU}" stroke-width="4"/>${TH_T(76,88,'M',{fs:30,fw:800,a:'middle',fill:BLU})}
  <circle cx="226" cy="78" r="40" fill="#EBFBEE" stroke="${GRN}" stroke-width="4"/>${TH_T(226,88,'G',{fs:30,fw:800,a:'middle',fill:GRN})}
  ${TH_arrow(118,62,182,62,TH_DARK,4,14)}${TH_arrow(184,96,120,96,TH_DARK,4,14)}
  ${TH_L(266,78,300,78,TH_DARK,3)}<circle cx="326" cy="70" r="22" fill="#FFF3BF" stroke="${YEL}" stroke-width="4"/><rect x="316" y="92" width="20" height="14" fill="${TH_STEEL}"/>
  ${TH_T(190,152,'no fuel, forever?',{fs:24,fw:800,a:'middle',fill:RED})}</g>`;
 ICON.thTurbHook=(x,y)=>`<g transform="translate(${x-190} ${y-85})">${TH_box(0,0,380,170,{fill:'#FFFFFF',st:BLU,sw:3,r:18})}
  ${TH_turb(190,72,120,44,96)}${TH_arrow(20,72,130,72,ORG,5)}${TH_arrow(250,72,360,72,GRN,5)}${TH_arrow(190,124,190,96,BLU,4,12)}
  ${TH_T(30,52,'steam in',{fs:20,fw:700,fill:ORG})}${TH_T(360,52,'out',{fs:20,fw:700,a:'end',fill:GRN})}
  ${TH_T(190,154,'energy in = energy out + work',{fs:22,fw:800,a:'middle',fill:BLU})}</g>`;
 /* card icons, centred on (x,y), about 200 × 120 */
 ICON.thNoz=(x,y)=>`<g transform="translate(${x} ${y})"><path d="M-90,-50 L60,-18 L90,-18 L90,18 L60,18 L-90,50 Z" fill="${TH_SKY}" stroke="${BLU}" stroke-width="4" stroke-linejoin="round"/>${TH_arrow(-80,0,-30,0,BLU,4,12)}${TH_arrow(10,0,110,0,BLU,6,16)}</g>`;
 ICON.thTurb=(x,y)=>`<g transform="translate(${x} ${y})">${TH_turb(0,0,140,40,100,ORG,'#FFF4E6')}${TH_arrow(-110,0,-70,0,ORG,4,12)}${TH_arrow(70,0,110,0,ORG,4,12)}${TH_L(0,-48,0,-70,TH_DARK,5)}${TH_arrow(0,-70,60,-70,GRN,4,12)}</g>`;
 ICON.thComp=(x,y)=>`<g transform="translate(${x} ${y})">${TH_turb(0,0,140,100,40,PUR,'#F3F0FF')}${TH_arrow(-110,0,-70,0,PUR,4,12)}${TH_arrow(70,0,110,0,PUR,4,12)}${TH_arrow(60,-70,4,-70,RED,4,12)}${TH_L(0,-70,0,-48,TH_DARK,5)}</g>`;
 ICON.thThr=(x,y)=>`<g transform="translate(${x} ${y})">${TH_L(-110,-22,110,-22,TH_DARK,4)}${TH_L(-110,22,110,22,TH_DARK,4)}<polygon points="-18,-22 18,-22 0,-4" fill="${GRN}"/><polygon points="-18,22 18,22 0,4" fill="${GRN}"/>${TH_L(0,-22,0,-56,TH_DARK,4)}${TH_L(-16,-56,16,-56,TH_DARK,5)}${TH_arrow(-100,0,-34,0,GRN,4,12)}${TH_arrow(34,0,100,0,GRN,4,12)}</g>`;
 /* recap pictures, each filling most of its card (about 420 × 330) */
 ICON.thBars=(x,y)=>{let s='';const k=0.6;
  [['(a)',300,500],['(b)',200,250],['(c)',80,60]].forEach(([n,q,w],i)=>{const yy=20+i*110;
   s+=TH_T(0,yy+40,n,{fs:24,fw:800,fill:TH_DARK})+TH_bar(48,yy,q*k,30,ORG)+TH_bar(48,yy+38,w*k,30,GRN)+
   (w>q?TH_T(48+w*k+12,yy+62,'✕',{fs:30,fw:800,fill:RED}):TH_bar(48+w*k,yy+38,20*k,30,TH_STEEL,{out:1,dash:1})+TH_T(48+80*k+16,yy+62,'✓',{fs:30,fw:800,fill:GRN}))});
  return `<g transform="translate(${x-200} ${y-160})">${s}</g>`};
 ICON.thCV=(x,y)=>`<g transform="translate(${x-210} ${y-150})"><rect x="110" y="30" width="200" height="220" rx="12" fill="none" stroke="${TH_GREY}" stroke-width="3" stroke-dasharray="10 8"/>
  ${TH_turb(210,140,130,70,170)}${TH_arrow(0,140,144,140,ORG,6)}${TH_arrow(276,140,420,140,GRN,6)}${TH_arrow(276,80,400,80,BLU,5)}${TH_arrow(210,226,210,300,TH_GREY,4)}
  ${TH_T(10,124,'in 1',{fs:24,fw:800,fill:ORG})}${TH_T(420,178,'out 2',{fs:24,fw:800,a:'end',fill:GRN})}${TH_T(400,64,'w',{fs:26,fw:800,a:'end',fill:BLU})}${TH_T(226,296,'q',{fs:26,fw:800,fill:TH_GREY})}</g>`;
 ICON.thStrike=(x,y)=>{const st=(x1,y1,x2)=>TH_L(x1,y1,x2,y1-26,RED,4);
  return `<g transform="translate(${x-232} ${y-170}) scale(1.25)">${TH_T(185,40,'insulated turbine',{fs:24,fw:800,a:'middle',fill:ORG})}
  ${TH_T(10,110,'h₁ + KE₁ + PE₁ + q',{fs:30,fw:800,fill:TH_DARK})}${st(84,116,150)}${st(160,116,226)}${st(236,116,262)}
  ${TH_T(10,170,'= h₂ + KE₂ + PE₂ + w',{fs:30,fw:800,fill:TH_DARK})}${st(110,176,176)}${st(186,176,252)}
  ${TH_box(35,210,300,64,{fill:'#EBFBEE',st:GRN,sw:3,r:10})}${TH_T(185,252,'w = h₁ − h₂',{fs:30,fw:800,a:'middle',fill:GRN})}</g>`};
}
